clean=[e for e in events if e['event_type']=='clean']
proc_by_op={e['operation_id']:e for e in proc}
print('multi-op batches', sum(1 for c in Counter(e['batch_id'] for e in proc).values() if c>1))
print('top duplicate batch sizes', Counter(Counter(e['batch_id'] for e in proc).values()))
print('clean events', clean)
# durations spot-check mismatch count
bad=[]
for e in proc:
    op=ops[e['operation_id']]
    exp=float(op['base_process_min'])*qual[(e['machine_id'],op['recipe_id'])]
    dur=float(e['end_min'])-float(e['start_min'])
    if abs(dur-exp)>1e-3:
        bad.append((e['operation_id'],e['machine_id'],dur,exp))
print('duration mismatches',len(bad),'sample',bad[:5])
